ATTACH DATABASE '' AS aux; PRAGMA aux.cache_size=-100; CREATE TABLE aux.t1(a INTEGER PRIMARY KEY, b); WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<100) INSERT INTO aux.t1 SELECT x, substr(replace(hex(zeroblob(450)), '00', CAST(x AS TEXT) || '.'), 1, 900) FROM c; WITH v(s) AS (SELECT substr(replace(hex(zeroblob(450)), '00', '1001.'), 1, 900)) INSERT INTO aux.t1 SELECT 10001, s || s || s FROM v; INSERT INTO main.result SELECT b FROM aux.t1 WHERE a=10001; DETACH DATABASE aux;